const memoize = (expensiveCalcFunc) => {
   const cache = new Map();  // Create a Map to store cached results
    return (...args) => {

     const key = JSON.stringify(args);  // Create unique key based on function arguments

      if (cache.has(key)) {
       return cache.get(key);  // Return cached result if it exists
     }

      const result = expensiveCalcFunc(...args);  // Calculate result for expensive operation
     cache.set(key, result);  // Store the result in cache
     return result;  // Return the computed result
   };
 };

 const expensiveCalcFunc = (a, b) => a + b;

 const memoizedAddition = memoize(expensiveCalcFunc);

 console.log(memoizedAddition(10, 20)); // Computes and caches result
 console.log(memoizedAddition(10, 20)); // Retrieves result from cache
 console.log(memoizedAddition(15, 25)); // Computes and caches result

// Using lodash
const memoizedFibonacci = memoize(function fib(n) {
   if (n <= 1) return n;
   return fib(n - 1) + fib(n - 2);
});

console.log(memoizedFibonacci(10)); // Output: 55, calculates and caches intermediate results
console.log(memoizedFibonacci(10)); // Output: 55, retrieves from cache

