function getCookieValue(cookieName) {
   const cookies = document.cookie.split("; ");
   // console.log(cookies);  // [username=OmkeshJadhav; isLoggedIn=true]

   for (let cookie of cookies) {
       const [key, value] = cookie.split("=");
       if (key === cookieName) {
           return value;
       }
   }
   return null;
}

